// Golden master of the CURRENT behaviour. Contract: test/contract/orders-api.contract.yaml
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the downstream pricing service.
const prices = { A: 40, B: 100, C: 101, D: 2.5, E: 19.99, F: 0.1 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const totalOf = async (items) => (await (await post({ items })).json()).total

test('POST /orders 201: returns id, items and total; consults pricing per item', async () => {
  calls.length = 0
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const body = await res.json()
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'A', qty: 2 }], total: 80 })
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(calls, ['A'])
})

test('POST /orders: ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total: sums price*qty across items', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 0 }, { sku: 'A', qty: 1 }]), 80)
})

test('discount: no discount at exactly 100 (threshold is strictly > 100)', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 1 }]), 100)
})

test('discount: 10% off once the sum exceeds 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 3 }]), 108) // 120 -> 108
})

test('discount: just above threshold', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - 101 * 0.9 = 90.9 is floored to 90,
  // so a 101 order is cheaper than the 100 order's 100 by more than 10%.
  assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 90)
})

test('discount: flat 10% for any large order, no tiers', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - a 10,000 order gets the same 10% as a 101 order.
  assert.equal(await totalOf([{ sku: 'B', qty: 100 }]), 9000)
  assert.equal(await totalOf([{ sku: 'B', qty: 1000 }]), 90000)
})

test('discount: fractional results floor to whole euros', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - cents are truncated, not rounded,
  // even without a discount (7.5 -> 7), and after the discount (119.94 -> 107.946 -> 107).
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 7)
  assert.equal(await totalOf([{ sku: 'E', qty: 6 }]), 107)
})

test('total: floating point sums are floored', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - binary float error is visible after floor.
  assert.equal(await totalOf([{ sku: 'F', qty: 3 }]), 0)
})

test('POST /orders 400: missing, empty, non-array items and invalid JSON', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, '{bad')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id 200: returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id unknown id', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - "not found" is answered with status 200, not 404.
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods answer 404 no route', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
